window.DGNL_DE_MON["l4"] = {"id": "l4", "ten": "Đề thi thử số 4", "tv": [{"noiDungChung": null, "cauHoi": [{"question": "Đọc đoạn trích sau:<br><i>Sinh vốn vì sự tìm vợ mà đến đây[...] Bấy giờ nhà trạm vắng tanh không có ai mà hỏi han cả. Chợt gặp một bà già, hỏi thăm thì bà cau mày bảo [...] Sinh giật mình hỏi, bà già nói:</i><br><i>- Trước đây năm hôm, quân Tầu sắp rút, người đàn bà họ Nguyễn ấy bảo với hai bà phu nhân họ Chu họ Trịnh rằng: &quot;Bọn chúng ta vóc mềm tựa liễu, mệnh bạc như vôi, nước vỡ nhà tan lưu ly đến đó. Nay nếu lại theo họ sang qua cửa ải tức là đến nước non quê người. Chẳng thà chết rấp ở ngòi lạch, gần gũi quê hương, còn hơn là sang làm những cái cô hồn ở bên đất Bắc&quot;. Thế rồi mấy người đều cùng nhau tự tận. Tướng Tầu thương là có tiết tháo, dùng lễ mà táng ở trên núi.</i><br>(Chuyện Lệ Nương, Nguyễn Dữ)<br>Qua đoạn trích trên, nhận định nào sau đây đúng nhất về nhân cách của vợ Sinh?", "choices": ["Là người phụ nữ cam chịu số phận, buông xuôi trước biến động lịch sử và chiến tranh.", "Là người phụ nữ giàu tình cảm cá nhân nhưng đặt hạnh phúc riêng lên trên lợi ích cộng đồng.", "Là người phụ nữ coi trọng tiết hạnh, lòng trung trinh và ý thức sâu sắc về quê hương, danh dự.", "Là người phụ nữ hành động bồng bột, cực đoan khi lựa chọn cái chết để giải quyết bi kịch."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đọc đoạn trích sau:<br><i>Tôi nghe kẻ cướp nó lèn ông,</i><br><i>Nó lại lôi ông đến giữa đồng.</i><br><i>Lấy của đánh người, quân tệ nhỉ!</i><br><i>Thân già da cóc, có đau không? [...]</i><br>(Hỏi thăm quan tuần mất cướp, Nguyễn Khuyến)<br>Đâu là nhận định <b>đúng nhất</b> về nét phong cách của Nguyễn Khuyến được phản ánh trong đoạn thơ trên?", "choices": ["Giọng thơ trang trọng, ước lệ, thiên về ngợi ca lý tưởng đạo đức.", "Lối viết trào phúng sắc sảo để phê phán hiện thực xã hội.", "Bút pháp lãng mạn, giàu chất mộng mơ và cảm hứng thoát li thực tại.", "Giọng điệu phê phán trào lộng, gây cười bằng phép đối tương phản."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đọc đoạn trích sau:<br><i>Đoài: Chú em ơi, anh không tranh luận với chú về các thiên kiến đạo đức. Đạo đức là thứ xa xỉ trong môi trường chật hẹp. Tôi hỏi chú: với một căn nhà 20 mét vuông, 7 mạng người chen chúc sống trong đó, mỗi người chưa được 3 mét vuông sinh sống, đồ đạc không có chỗ để, vậy đạo đức để vào đâu?</i><br><i>Khảm: Im đi! Im đi!</i><br><i>Đoài: Còn điều này nữa. Chú phải hiểu đạo đức chỉ là một khái niệm trừu tượng, không có thực, không nắm bắt được. Bao giờ nhìn một mâm cơm chú khen: &quot;Mâm cơm này có đạo đức đấy&quot;. Ăn một quả chuối, chú khen: &quot;Quả chuối này có đạo đức đấy”, ở một căn nhà, chú khen: &quot;Căn nhà này có đạo đức đấy&quot;. Thế là chú đạt được đến độ tinh thông của tư tưởng. Lúc ấy, chú không còn thiên kiến. Đạo đức thực sự cũng là môi trường, chú ạ. Con người bé nhỏ chúng ta ôm ấp đạo đức trong một môi trường vô luân thì sẽ bi kịch cả thôi.</i><br><i>Khảm (ôm đầu): Im đi! Im đi! Tôi đau đầu lắm.</i><br><i>Đoài (cười nhạt): Thế chú tưởng tôi không đau đầu ư? Không xót xa ư? Không đau đớn ư? Tôi không có óc ư? Không có tim ư? Tôi là người. Chú hiểu không? Tôi cũng là người!</i><br>(Quỷ ở với người, Nguyễn Huy Thiệp)<br>Đâu là phương án nêu <b>đúng nhất</b> xung đột tư tưởng có trong đoạn trích?", "choices": ["Sự đối lập giữa người có học thức và người thiếu hiểu biết trong cách nhìn nhận đạo đức.", "Mâu thuẫn giữa lí tưởng đạo đức trừu tượng và điều kiện sống vật chất ngột ngạt của con người.", "Cuộc tranh cãi giữa cá nhân tin vào đạo đức tuyệt đối và người cho rằng đạo đức tuỳ thuộc vào hoàn cảnh.", "Sự xung đột giữa cá nhân muốn giữ đạo đức và cá nhân không có đạo đức."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Từ thế kỉ X khi quốc gia đã giành được độc lập, để xây dựng nền học vấn, giáo dục, khoa cử và văn học của mình, người Việt đã buộc phải <b>di thực</b> cả một ngôn ngữ, văn tự ngoại lai là chữ Hán, văn ngôn, các thể loại, thậm chí cả phong cách, điển cố, thể thức diễn đạt trong văn bản hành chính và sáng tác văn thơ. (Văn học Việt Nam từ khu vực ra thế giới, từ truyền thống đến hiện đại, Trần Đình Sử)<br>Cụm từ <b>“di thực”</b> được sử dụng với ý nghĩa gì?", "choices": ["Sao chép nguyên vẹn hệ thống ngôn ngữ, văn tự và thể loại văn học từ Trung Hoa vào Việt Nam.", "Bị cưỡng ép tiếp nhận ngôn ngữ và văn tự ngoại lai trong quá trình xây dựng nhà nước phong kiến.", "Tiếp nhận và sử dụng có ý thức hệ thống ngôn ngữ, văn tự và thể loại văn học từ Trung Hoa", "Thay thế hoàn toàn ngôn ngữ bản địa bằng chữ Hán"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu đúng", "choices": ["Anh ấy cắt miếng thịt, cảm nhận độ ngọt của thịt và bỏ vào miệng.", "Chiều hôm ấy, một buổi chiều với bầu trời màu đỏ rực.", "Gió nổi lên, mây đen kéo đến.", "Tuy giá cao nhưng cửa hàng vẫn vắng khách."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đâu là phương án sửa phù hợp <b>nhất</b> cho câu sai: “Bằng tri thức và kĩ năng lĩnh hội được từ những năm tháng thực chiến, những nhà tuyển dụng đã hoàn toàn bị Đạt thuyết phục.”", "choices": ["Với tri thức và kĩ năng của mình, Đạt đã hoàn toàn thuyết phục được những nhà tuyển dụng trong những năm tháng thực chiến.", "Đạt đã hoàn toàn thuyết phục được những nhà tuyển dụng bằng tri thức và kĩ năng có được từ những năm tháng thực chiến.", "Tri thức và kĩ năng lĩnh hội từ những năm tháng thực chiến đã khiến những nhà tuyển dụng hoàn toàn bị thuyết phục bởi Đạt.", "Những năm tháng thực chiến, Đạt đã hoàn toàn thuyết phục những nhà tuyển dụng bằng tri thức và kĩ năng của mình."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Làm giật mình một cô nàng yếm thắm</i><br><b><i>Cúi cuốc cào cỏ</i></b><i> ruộng sắp ra hoa. </i>(Chiều thơ, Anh Xuân)<br>Cụm từ được in đậm chứa biện pháp tu từ gì?", "choices": ["Chơi chữ", "Điệp vần", "Điệp thanh", "Điệp ngữ"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>Vẫn nói, vẫn cười, vẫn ăn, vẫn uống,</i><br><i>Vẫn cao ngạo, tự tin, điềm tĩnh,</i><br><i>Nhưng trên gương mặt anh đã có gì khuất lấp,</i><br><i>Anh – người của thế kỷ khác rồi! </i><br>(Bằng Việt)<br>Tác dụng chính của biện pháp tu từ chêm xen trong đoạn thơ trên là gì?", "choices": ["Bổ sung cảm xúc bất ngờ cho đoạn thơ", "Nhấn mạnh sự chuyển đổi đầy bất ngờ của nhân vật “anh”", "Bổ sung thông tin về lai lịch của nhân vật “anh”", "Tạo nhạc tính cho đoạn thơ, khiến đoạn thơ giàu nhịp điệu"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu đúng", "choices": ["Những nổ lực của bạn sẽ mang lại phần thưởng", "Tựu chung, thất bại lần này là do sự thiếu khách quan.", "Vì mãi mê với những trò tiêu khiển, cậu đã để cho việc học sa sút.", "Anh cứ lần lữa, không dám đưa ra quyết định dứt khoát."], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Tục truyền, thời Hùng Vương, có một công chúa xinh đẹp là Hoàng Phủ Thiều Hoa không thích ở vùng Nghĩa Lĩnh[...] Công chúa tuổi ngày một cao nhưng vẫn không muốn lấy chồng, chỉ một lòng chuyên nghề canh cửi. Công chúa không ưng ý việc ép gả của vua cha nên bèn bỏ trốn sang trang Cổ Sắt. Đến đây, công chúa dạy dân trồng dâu nuôi tằm và dệt lụa. Hết dạy cho dân Cổ Đô, Vân Sa lại còn mang nghề sang truyền bá cho hơn 60 làng xung quanh. Vì vậy mà sau này, làng Cổ Đô và Vân Sa dệt lụa nổi tiếng là đẹp và bền, nhân dân vùng Sơn Tây cũ còn truyền tụng lại câu ca:</i><br><i>Lụa này thật lụa Cổ Đô</i><br><i>Chính tông lụa cống, các cô ưa dùng.</i><br><i>Tương truyền, nghề canh cửi này dần dần được lan truyền sang các vùng khác trong đất Hà Tây và truyền tới nhiều làng thuộc các tỉnh Hà Nam, Nam Định, Ninh Bình, Thái Bình ngày nay. </i><br>Đoạn trích trên không phản ánh đặc trưng nào của thể loại truyền thuyết?", "choices": ["Gắn với nhân vật và bối cảnh lịch sử xa xưa", "Mang tính truyền miệng, dân gian, được lưu truyền qua nhiều thế hệ", "Có yếu tố kì ảo, hoang đường", "Giải thích nguồn gốc, sự hình thành của truyền thống văn hóa cộng đồng"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đọc đoạn trích sau<br>Ông rằng: “Bỉ thử nhất thì,<br>Tu hành thì cũng phải khi <b><i>tòng quyền.</i></b><br>Phải điều cầu Phật cầu tiên,<br>Tình kia, hiếu nọ, ai đền cho đây?”<br>(Truyện Kiều, Nguyễn Du)<br>Phương án nào giải thích <b>đúng nhất</b> ý nghĩa của cụm từ được in đậm trong văn cảnh trên?", "choices": ["Tuân theo quyền lực và mệnh lệnh của người có địa vị cao hơn.", "Tạm thời linh hoạt, ứng xử theo hoàn cảnh chứ không cứng nhắc.", "Từ bỏ các quy chuẩn đạo đức để hành động theo ý muốn cá nhân.", "Chấp nhận thỏa hiệp với số phận và buông xuôi trước nghịch cảnh."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Trong văn học trung đại Việt Nam, nghệ thuật biểu hiện thường gắn liền với bút pháp __________, sử dụng những hình ảnh quen thuộc như trăng, hoa, tuyết, nguyệt để gợi tả con người và cảm xúc. Tuy nhiên, việc quá đề cao khuôn mẫu cũ đôi khi khiến sáng tạo nghệ thuật rơi vào tình trạng ___________ làm hạn chế khả năng phản ánh đời sống hiện thực sinh động và cá tính riêng của người nghệ sĩ.", "choices": ["ước lệ tượng trưng – nệ cổ, sùng cổ", "hiện thực – cổ điển chủ nghĩa", "lãng mạn – xa rời thực tế", "tả thực – bê nguyên xi hiện thực đời sống"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đọc đoạn trích sau<br>“Não người cữ gió tuần mưa,<br>Một ngày nặng <b><i>gánh tương tư</i></b> một ngày.”<br>(Truyện Kiều, Nguyễn Du)<br>Cụm từ in đậm sử dụng biện pháp tu từ gì?", "choices": ["Nhân hoá", "Nói quá", "Ẩn dụ", "Hoán dụ"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Bữa họ đưa Quý đi, chị đã chân không theo tới cây ô môi gãy ngọn đứng kia. Không phải vì vượt qua cái cây là ra khỏi Xẻo Đắng mà chị dừng lại. Chỉ vì ở đó tiếng canô thật sự tuyệt mù, cả sóng cũng không còn gợn. (Theo Đường về Xẻo Nắng, Nguyễn Ngọc Tư)<br>Có bao nhiêu động từ trong đoạn trích trên?", "choices": ["7", "8", "9", "10"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Văn học Việt Nam giai đoạn này, với sự đóng góp của __________ đã xuất hiện những thể loại văn học mới như: ca trù, diễn ca, truyện thơ lục bát, song thất lục bát và truyện thơ luật Đường. Đây là những thể loại sử dụng ngôn ngữ thi ca dân tộc.", "choices": ["văn học chữ Hán", "văn học chữ Nôm", "văn học dân gian", "văn học hiện đại"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<b>Co ro trong chiếc áo bông chùng lượt thượt</b>, ông cố thu hết vào lòng cái ấm của vải dạ và của ngọn đèn dầu lạc búp măng, giữa một khay đèn tắt mắt, chải chuốt. (Cái bào thai, Nguyên Hồng)<br>Thành phần được in đậm là thành phần gì?", "choices": ["Khởi ngữ", "Trạng ngữ", "Vị ngữ", "Chủ ngữ"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn phương án chứa từ đúng chính tả.", "choices": ["trí mạng", "đường xá", "phố sá", "xơ xài"], "correctIndex": 0, "explain": "Hướng dẫn: <b>Trí mạng</b> (致命) là từ Hán Việt chỉ hành động, sự việc gây nguy hiểm nghiêm trọng đến tính mạng, có khả năng dẫn đến tử vong.<br>Câu B. Đường xá \\(\\rightarrow \\ \\)Đường sá<br>Câu C. Phố sá \\(\\rightarrow\\) Phố xá<br>Câu D. xơ xài \\(\\rightarrow\\) sơ sài"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Nhận định nào sau đây phân biệt <b>đúng nhất</b> giữa phóng sự và nhật kí?", "choices": ["Phóng sự ghi chép các sự kiện có thật mang tính thời sự, còn nhật kí ghi lại những sự việc mà người viết nhớ lại.", "Phóng sự sử dụng ngôi kể thứ ba khách quan, còn nhật kí luôn sử dụng ngôi kể thứ nhất.", "Phóng sự phản ánh và bình luận các vấn đề xã hội, còn nhật kí chủ yếu là ghi chép mang tính cá nhân, riêng tư.", "Phóng sự luôn được công bố rộng rãi, còn nhật kí là tài sản riêng tư, cá nhân."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Sau khi nhận lấy phiếu báo điểm, thầy yêu cầu các học sinh nêu ý kiến nếu có.</i><br>Câu trên mắc lỗi gì?", "choices": ["Sai ngữ pháp", "Sai logic", "Sai quy chiếu", "Câu trên không mắc lỗi"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn phương án chứa từ “mấy” là phương ngữ", "choices": ["Chỉ còn mấy tháng nữa là Tết.", "Mấy người ở ngoài kia làm gì mà ồn ào thế?", "Thằng Tí bảo: “Chị cho em chơi chung với mấy!”", "Mẹ quay sang hỏi tôi: “Bây giờ là mấy giờ rồi?”."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<b>Trí tuệ nhân tạo có thể làm thay đổi căn bản trường học vào năm 2050</b><br><i>(1) Đến năm 2050, nền giáo dục sẽ khác xa so với hiện nay, theo nhận định của Howard Gardner, cha đẻ của thuyết đa trí thông minh, và Anthea Roberts, giáo sư thỉnh giảng tại Trường Luật Harvard, đồng thời là nhà sáng lập và Giám đốc điều hành công cụ AI Dragonfly Thinking. Gardner cho rằng mô hình giáo dục truyền thống, vốn cho rằng học sinh cùng học một nội dung và được đánh giá theo cùng một cách, sẽ trở nên lỗi thời. Trong tương lai, mỗi học sinh chỉ cần vài năm để nắm vững các kỹ năng nền tảng như đọc, viết, tính toán và một chút lập trình. Sau đó, giáo viên sẽ đóng vai trò như những người huấn luyện, giúp học sinh khám phá tư duy, tiếp cận ý tưởng mới và định hướng nghề nghiệp phù hợp với đam mê cá nhân.</i><br><i>(2) Sự phát triển của AI cũng khiến Gardner xem xét lại những quan niệm trước đây về các năng lực nhận thức cốt lõi. Ông từng đề xuất năm kiểu tư duy mà giáo dục cần phát triển, trong đó có tư duy kỷ luật (học tập các môn như lịch sử, sinh học hoặc toán học); tư duy tổng hợp (kết nối các mạch tư tưởng theo những cách hợp lý); và tư duy sáng tạo (“Đây là kiểu tư duy mà tất cả chúng ta đều quan tâm nhưng lại rất hiếm: đó là khả năng tạo ra một điều gì đó mới mẻ và thực sự có sức bền,” Gardner nói). Hai kiểu tư duy còn lại - tư duy tôn trọng và tư duy đạo đức - giúp chúng ta ứng xử với người khác và đối diện với những vấn đề xã hội phức tạp. Tuy nhiên, theo Gardner, các hệ thống AI có thể sớm thực hiện tốt đến mức vượt trội ba kiểu tư duy đầu tiên, khiến việc con người đảm nhiệm chúng trở thành lựa chọn hơn là yêu cầu bắt buộc.</i><br><i>(3) Trước thực tế đó, giáo dục đứng trước thách thức lớn: làm sao để AI không thay thế mà mở rộng năng lực nhận thức của con người. Việc học sinh dựa dẫm quá mức vào AI có thể làm suy giảm tư duy phản biện, nhưng nếu được định hướng đúng đắn, AI có thể trở thành công cụ giúp con người phát triển sâu sắc hơn về nhân cách và trách nhiệm xã hội. Roberts cho biết bà buộc phải gác lại sách vở học thuật và bắt đầu phát triển các công cụ trí tuệ nhân tạo sau khi một đồng nghiệp trẻ hơn phát triển một “Robo-Anthea” có thể trò chuyện trôi chảy từ góc nhìn của bà. Roberts cho biết. “Trong tất cả các công việc học thuật của mình, tôi đều mở Gemini, GPT và Claude để đối thoại. … Tôi cung cấp câu trả lời của các ứng dụng này cho nhau. Tôi liên tục trò chuyện với cả ba mô hình ngôn ngữ này.” </i><br>(Sy Boles, How AI could radically change schools by 2050, Harvard Gazette, 19 tháng 9, 2025.)", "cauHoi": [{"question": "Mục đích chính của việc trích dẫn quan điểm của cả Howard Gardner và Anthea Roberts trong văn bản là gì?", "choices": ["Tạo thế đối lập giữa lý thuyết giáo dục truyền thống và công nghệ hiện đại", "Minh chứng rằng AI đang gây tranh cãi trong giới học thuật", "Kết hợp lập luận học thuật với trải nghiệm thực tiễn để làm rõ vấn đề", "Khẳng định vai trò tích cực của AI trong giáo dục"], "correctIndex": 2, "explain": ""}, {"question": "Từ việc Gardner cho rằng ba kiểu tư duy có thể trở thành “không bắt buộc”, người đọc có thể suy ra điều gì về mục tiêu cốt lõi của giáo dục trong tương lai?", "choices": ["Đào tạo con người có năng lực cạnh tranh với AI về mặt trí tuệ", "Tập trung vào phát triển năng lực liên quan đến nhân cách, đạo đức", "Giảm thời lượng học tập để tăng thời gian sử dụng công nghệ", "Chuyển trọng tâm giáo dục sang đào tạo kỹ năng nghề ngắn hạn"], "correctIndex": 1, "explain": ""}, {"question": "Chi tiết Anthea Roberts “liên tục đối thoại với các mô hình ngôn ngữ lớn” nhấn mạnh điều gì?", "choices": ["AI đã trở thành chủ thể sáng tạo độc lập trong nghiên cứu học thuật.", "Nhà giáo dục sử dụng AI để ứng phó trước việc người học lạm dụng AI.", "Các học giả trẻ đang thích nghi với AI nhanh hơn thế hệ trước.", "AI có thể trở thành những cộng sự học thuật hữu dụng."], "correctIndex": 3, "explain": ""}, {"question": "Thông tin cơ bản được trình bày trong văn bản trên là gì?", "choices": ["Trí tuệ nhân tạo đang trở thành mối đe doạ cho con người trong hoạt động giáo dục và nghiên cứu học thuật.", "Quan điểm của các học giả về việc ứng dụng trí tuệ nhân tạo trong giảng dạy luật tại Đại học Harvard.", "Tác động của trí tuệ nhân tạo đối với mô hình giáo dục trong tương lai và những vấn đề đặt ra cho giáo dục con người.", "Sự khác biệt trong cách tiếp cận trí tuệ nhân tạo giữa các thế hệ học giả."], "correctIndex": 2, "explain": ""}, {"question": "Cách trình bày thông tin trong đoạn (2) là gì?", "choices": ["Trật tự thời gian", "Vấn đề - Cách giải quyết", "Thông tin chính – Thông tin chi tiết", "Nguyên nhân - Kết quả"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<b><i>(1)</i></b><i> Quá trình đô thị hóa và đẩy mạnh phát triển công nghiệp đã diễn ra khắp nơi trên cả nước, từ miền xuôi lên miền ngược, với tốc độ nhanh chóng đã thay đổi đáng kể bộ mặt nông thôn. Tuy nhiên, song song với việc mang lại những chuyển biến tích cực về đời sống vật chất, quá trình đô thị hóa đã khiến con người không tránh khỏi những tổn thương về tinh thần, nó bộc lộ rõ sự suy thoái về mặt đạo đức, khi đồng tiền và chủ nghĩa thực dụng lên ngôi nhiều giá trị thuộc về văn hóa bị đánh tráo khái niệm. Lối sống công nghiệp vội vã, xô bồ, ồn ào dễ làm con người rơi vào trạng thái hoang mang, hoài nghi, mất niềm tin vào thế giới xung quanh. Con người có xu hướng dành thời gian quan tâm đến việc phát triển kinh tế, kiếm nhiều tiền, mưu sinh, làm giàu hơn là đầu tư cho việc đọc sách nói chung và đọc văn học nói riêng. Nhu cầu vật chất lấn át nhu cầu về tinh thần, vì vậy mới có tình trạng hiện nay không có nhiều độc giả bỏ tiền mua sách văn học, lại càng ít người “sống chậm”, trầm tư trong tĩnh lặng để nghiền ngẫm về những điều thú vị của văn chương. Bên cạnh đó, các phương tiện thông tin đại chúng khác nhiều tính năng hấp dẫn đang phát triển rầm rộ, tác động từng khoảnh khắc đến con người ở mọi nghề nghiệp, lứa tuổi…tất cả khiến văn học trở nên rất khó khăn để tìm chỗ đứng trong lòng độc giả.</i><br><b><i>(2)</i></b><i> Theo khảo sát gần đây nhất: “Việt Nam chỉ có 30% số người đọc sách thường xuyên, 26% không đọc sách và 44% thỉnh thoảng đọc sách. Đồng thời, thời gian dành cho đọc sách của người Việt Nam khoảng một giờ, thuộc nhóm thấp nhất trên thế giới. Còn theo số liệu khảo sát của Viện nghiên cứu Xã hội, Kinh tế và Môi trường về việc sử dụng thời gian rảnh để làm việc gì là chủ yếu, có đến 41,7% số bạn trẻ trả lời là lên mạng, 20% xem phim, 16,7% nghe nhạc và chỉ có 15% trả lời là đọc sách. Và trong một khảo sát đối với sinh viên TP.HCM, có 47,26% sinh viên nhận thức được tầm quan trọng của sách, 26.37% nghĩ rằng đọc sách là cần thiết, 25,15 cho rằng việc đọc sách là bình thường, có hay không cũng được và 1,22% nghĩ rằng việc đọc sách là không cần thiết”(3)…Thực trạng văn hóa đọc theo điều tra trên là rất đáng để chúng ta suy nghĩ. Đó là chưa kể đến việc văn hóa nghe, nhìn đang có phần lấn át văn hóa đọc của cộng đồng. Và còn một thực tế không thể phủ nhận, đó là việc đọc sách của nhiều học sinh, sinh viên, những người trẻ tuổi ngày nay hầu như chỉ theo phong trào, đọc vì sự tò mò, và nếu có đọc thì thường chọn những loại truyện ngôn tình, những loại sách đen, có nội dung “hót”. Họ đọc văn học mục tiêu chỉ đơn thuần để giải trí vui vui, chính vì vậy, bạn đọc văn học “dễ dãi” với bản thân, không hề băn khoăn, suy tư sâu sắc về ý nghĩa của tác phẩm là gì? Đọc xong tác phẩm có thức nhận được vấn đề gì trong/cho cuộc sống hay không?</i><br><b><i>(3)</i></b><i> Tiếp nhận văn học đòi hỏi nhiều ở người đọc một tâm thế chủ động trong việc thâm nhập vào các vỉa tầng, lớp lang của cấu trúc nghệ thuật để đi tìm mỹ cảm văn chương, đọc ra lớp lớp thông điệp sau hình ảnh ngôn từ. Câu chuyện về vốn sống, vốn văn hóa, trình độ, kinh nghiệm thẩm mỹ, các quan niệm và độ sâu trong quan niệm về giá trị…chính là vấn đề của tâm thế tiếp nhận. Tuy nhiên, công chúng phổ thông hiện nay, với muôn vàn thúc bách của cuộc sống thời kỹ trị lạnh lùng, vô cảm họ phải chạy đua với thời gian để ưu tiên những việc mà họ cho là quan trọng, cấp bách hơn, do vậy vấn đề tự ý thức để trau dồi tri thức, vốn văn hóa, nâng cao “tầm đón nhận” của bạn đọc còn nhiều giới hạn.</i><br>(Cao Thị Hồng)", "cauHoi": [{"question": "Đâu là nhan đề phù hợp nhất cho văn bản trên?", "choices": ["Văn học trong đời sống tinh thần của con người hiện đại", "Thực trạng văn hóa đọc và những thách thức của văn học trong xã hội đương đại", "Sự phát triển của công nghiệp và tác động đến đời sống văn học Việt Nam", "Vai trò của sách văn học đối với học sinh, sinh viên hiện nay"], "correctIndex": 1, "explain": ""}, {"question": "Tác giả sử dụng bằng chứng nào để làm rõ thực trạng văn hóa đọc đang suy giảm?", "choices": ["Mô tả lối sống công nghiệp vội vã, xô bồ của con người hiện đại.", "Trình bày tác động của đô thị hóa đến đời sống tinh thần con người.", "Dẫn các số liệu khảo sát về tỉ lệ đọc sách và thói quen giải trí của người Việt Nam.", "Mô tả thị hiếu đọc sách ngôn tình và sách “hot” của giới trẻ."], "correctIndex": 2, "explain": ""}, {"question": "Trong văn bản, cụm từ “thời kỹ trị” được hiểu đúng nhất là gì?", "choices": ["Thời đại con người đề cao lao động thủ công hơn là lao động trí óc.", "Thời đại khoa học – công nghệ chi phối mạnh mẽ đời sống xã hội.", "Thời kì xã hội phát triển kinh tế vượt bậc dựa vào lao động trí óc.", "Thời đại phát triển mạnh các ngành công nghiệp nặng."], "correctIndex": 1, "explain": ""}, {"question": "Luận điểm chính của đoạn (1) là gì?", "choices": ["Đô thị hóa và công nghiệp hóa làm thay đổi bộ mặt nông thôn Việt Nam.", "Sự phát triển kinh tế khiến con người ngày càng xa rời văn học.", "Hai mặt lợi - hại của quá trình đô thị hoá và sự tác động đến nhu cầu đọc văn học", "Con người hiện đại có xu hướng chạy theo đồng tiền và chủ nghĩa thực dụng."], "correctIndex": 1, "explain": ""}, {"question": "Đâu là nhận định không phù hợp với nội dung văn bản?", "choices": ["Khả năng tiếp nhận văn học của đa số người đọc là hạn chế.", "Trong quá trình đọc tác phẩm, người đọc cần sự chủ động.", "Việc đọc sách của không ít học sinh, sinh viên và người trẻ hiện nay chủ yếu mang tính phong trào.", "Vì nhu cầu vật chất chiếm ưu thế nên không nhiều người đọc bỏ tiền mua sách."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}], "anh": [{"noiDungChung": null, "cauHoi": [{"question": "<i class=\"huong-dan-cau\">Mark the letter A, B, C, or D on your answer sheet to indicate the correct answer to each of the following questions.</i><br>With greater access to would-be employers _______ a greater chance to make mistakes.", "choices": ["come", "comes", "coming", "have come"], "correctIndex": 1, "explain": "<b><i> B. comes.</i></b><i> </i><b><i>Đảo ngữ nhấn mạnh object, cụ thể với cụm “with greater access to would-be employers” là O, a greater chance to make mistakes là cụm S, suy ra mình sẽ có động từ chia theo số ít là “comes”.</i></b><br><b><i>Các trường hợp khác không đúng vì:</i></b><br><b><i>A. come không hợp với chủ ngữ số ít.</i></b><br><b><i>C. coming V-ing = gerune không thể làm động từ chính ở đây và cũng không có yếu tố để xuất hiện Gerund.</i></b><br>D. have come thì hiện tại hoàn thành không phù hợp ngữ cảnh chung chung."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Dominic had said he spoke German, but when we got there it turned out he _______ a word!", "choices": ["couldn’t speak", "couldn’t have spoken", "mightn’t speak", "mightn’t have spoken"], "correctIndex": 0, "explain": "<b><i> A. couldn’t speak, sử dụng quá khứ đơn diễn tả sự vật diễn ra được kể lại. </i></b><br><b><i>B. không phù hợp vì could + have thể hiện tình huống giả định ở quá khứ</i></b><br><b><i>C. không phù hợp về nghĩa</i></b><br><b><i>D. không có cấu trúc mightn’t have. </i></b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Sorry I’m late. I _______ a few things from the supermarket on my way here.", "choices": ["ought to have got.", "had better get.", "must have got.", "had to get."], "correctIndex": 3, "explain": "<b><i> D. had to get. Phù hợp về nghĩa. </i></b><br><b><i>Các cụm khác không phù hợp:</i></b><br><b><i>A, D modals + have + V3/ed cấu trúc giả định định ở tình huống quá khứ.</i></b><br><b><i>B modals had better = nên. </i></b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "They _______ over £5000 for their story.", "choices": ["are understood to have offered", "understood to have offered", "are understood to have been offered", "understood to have been offered"], "correctIndex": 2, "explain": "<b><i> C. are understood to have been offered. Đối chiếu từ cấu trúc it is + V3/ed + to + V1.</i></b><br><b><i>to have + V3/ed là hành động được cho là đã xảy ra ở quá khứ và to have been + offered là bị động Họ được cho là đã được trả 5000 pounds cho câu truyện của họ. </i></b><br><b><i>A chủ động, không phù hợp</i></b><br><b><i>B, D họ đã hiểu chủ động, không phù hợp.</i></b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "I honestly believe that _______ car is one of _______ worst inventions in _______ history of the world.", "choices": ["--- / the / the", "a / the / ---", "the / --- / a", "the / the / the"], "correctIndex": 3, "explain": "<b><i> D. the/the/the. The car chỉ về phương tiện nói chung, the worst so sánh nhất, và the history nhắc tới lịch sử xác định nói chung. </i></b><br><b><i>Các đáp án khác không phù hợp. </i></b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 36-40: </b>Mark the letter A, B, C, or D on your answer sheet to indicate the wrong word use/form to each of the following statement.", "cauHoi": [{"question": "Not only <b><u>the movie wa</u>s</b> hilarious, but <b><u>it</u></b> <b><u>also</u></b> had <b><u>a</u></b> touching message about friendship.", "choices": ["the movie was.", "it.", "also.", "a."], "correctIndex": 0, "explain": "<b><i> A the movie was was the movie. Cấu trúc đảo ngữ với Not only </i></b>"}, {"question": "The music shop <b><u>ordered</u></b> 50 copies of the <b>CD</b>, only <b>discovering</b> that the songs <b>were sung</b> in a foreign language.", "choices": ["ordered.", "CD", "discovering.", "were sung."], "correctIndex": 2, "explain": "<b><i> C. discovering to discover, thể hiện mục đích của “the music shop”.</i></b>"}, {"question": "“How long <b><u>have you stayed</u></b> together?” ---- “We <b><u>should</u></b> have been <b><u>married</u></b> for <b><u>twenty-three years</u></b> on our next anniversary.”", "choices": ["have you stayed.", "should.", "married.", "twenty-three years."], "correctIndex": 1, "explain": "<b><i> B. should will. Thể hiện tương lai sẽ xảy ra và đi kèm với hoàn thành</i></b>."}, {"question": "A highly valued animal fiber, <b><u>the</u></b> silk <b><u>has long been used</u></b> for the production of <b><u>luxuries</u></b> textiles of the <b><u>finest</u></b> quality..", "choices": ["the", "has long been used", "luxuries", "finest."], "correctIndex": 0, "explain": "<b><i> A. the - .Là nguyên liệu thường sẽ không có mạo từ để xác định. </i></b>"}, {"question": "<u><b>Having</u></b> unprepared for the final exam in all <b><u>those</u></b> subjects, I felt sure I <b><u>would</u></b> get incredibly low <b><u>scores</u></b>.", "choices": ["Having", "those", "would", "scores"], "correctIndex": 0, "explain": "<b><i> A. Having Having been hoặc being. Đề cập về việc unprepared đã diễn ra trước thời điểm final exam (hành động đó đã xảy ra và kết thúc) cho nên có thể dùng QKHT và QKD (tối giản) </i></b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 41-45: Which of the following best restates each of the given sentences?</b>", "cauHoi": [{"question": "Many students find it difficult to balance academic responsibilities with personal interests.", "choices": ["A large number of students struggle to manage both their studies and personal activities.", "Students are not interested in academic responsibilities.", "Personal interests prevent students from going to school.", "Only a few students care about balancing their time."], "correctIndex": 0, "explain": "<b><i> A. Many students = a large number of students, find it difficult = struggle, balance = manage, …</i></b>"}, {"question": "The rapid development of technology has significantly changed the way people communicate.", "choices": ["Technology has had little influence on modern communication.", "Advances in technology have greatly transformed communication methods.", "People communicate less because of technological progress.", "Communication methods have remained the same despite technology."], "correctIndex": 1, "explain": "<b><i> B. advances = the rapid development of technology, transformed = changed, communication methods = the way people communicate. </i></b>"}, {"question": "Although the task was challenging, she managed to complete it on time.", "choices": ["The task was too difficult for her to finish.", "She completed the task easily without any difficulty.", "Despite the difficulty, she succeeded in finishing the task punctually.", "She failed to finish the task because it was challenging."], "correctIndex": 2, "explain": "<b><i> C. Clause of Concession, although = despite. </i></b>"}, {"question": "Regular exercise not only improves physical health but also has a positive effect on mental well-being.", "choices": ["Exercise benefits the body but harms mental health.", "Physical health is more important than mental health.", "Exercising regularly contributes to both physical and mental health.", "Mental health can only be improved through exercise."], "correctIndex": 2, "explain": "<b><i> C. exercising regularly = regular exercise, physical health &amp; mental well-being = physical and mental health.</i></b>"}, {"question": "People are becoming increasingly aware of the importance of protecting the environment.", "choices": ["Environmental protection is no longer a major concern.", "More people now recognize the need to preserve the environment.", "Only scientists are interested in environmental issues.", "People are less worried about environmental damage than before."], "correctIndex": 1, "explain": "<b><i> B. More people now recognize = people are becoming increasingly aware of</i></b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 46-52: </b>Read the passage carefully<br>Vietnamese cultural identity is a rich and intricate tapestry that reflects the nation&#x27;s long and storied history. Rooted in over a thousand years of civilization, Vietnam&#x27;s cultural identity is a fusion of <b>indigenous </b>traditions and external influences, shaped by its geographical location and historical interactions.<br>First and foremost, at the heart of Vietnamese culture is a deep <b>reverence</b> for family and community. Confucian values emphasizing respect for elders, filial piety, and social harmony have played a pivotal role in shaping Vietnamese society. These values are reflected in the close-knit family structures, hierarchical relationships, and communal rituals that are integral to daily life.<br>Secondly, Vietnamese cuisine is celebrated worldwide for its exquisite flavors and diversity. With its emphasis on fresh ingredients, fragrant herbs, and balanced flavors, Vietnamese food tells a story of the country&#x27;s agricultural heritage and regional variations. Iconic dishes like pho, banh mi, and spring rolls have become global favorites, representing the culinary artistry deeply ingrained in Vietnamese culture. Also, Vietnam&#x27;s artistic expressions are equally captivating. Traditional art forms like water puppetry, silk painting, and folk music continue to thrive alongside contemporary artistic movements<b>. <u>Ao dai, a graceful traditional dress, exemplifies the fusion of elegance and modesty in Vietnamese fashion, symbolizing cultural pride and identity.</u></b><br>Today, in the face of modernization and globalization, Vietnamese cultural identity remains resilient. While adapting to the challenges of the 21st century, the Vietnamese people continue to honor <b>their </b>traditions, celebrate their unique cultural expressions, and pass on their heritage to future generations, ensuring that their cultural identity remains vibrant and enduring.", "cauHoi": [{"question": "The word <b>indigenous </b>in paragraph 1 is OPPOSITE in meaning to ________", "choices": ["local", "foreign", "native", "traditional"], "correctIndex": 1, "explain": "<b><i> B. foreign. </i></b><br><b><i>A, C, D lần lượt là local, native, traditional đâu đó có cùng nghĩa truyền đạt “thuộc về bản xứ”</i></b>"}, {"question": "Which of the following is NOT mentioned as Confucian values emphasizing respect for?", "choices": ["filial piety", "social harmony", "individualism", "elders"], "correctIndex": 2, "explain": "<b><i> C. individualism.</i></b><br><b><i>Trong paragraph 2 dòng 2 có đề cập “Confucian values emphasizing <u>respect for elders, filial piety</u>, and <u>social harmony</u> …” </i></b>"}, {"question": "The word <b>reverence </b>in paragraph 2 could be best replaced by _______", "choices": ["disrespect", "admiration", "indifference", "criticism"], "correctIndex": 1, "explain": "<b><i> B. admiration (n): sự ngưỡng mộ, tôn kính = reverence (n)</i></b><br><b><i>A. disrespect: khinh thường (trái nghĩa)</i></b><br><b><i>C. indifference: thờ ơ</i></b><br><b><i>D. criticism: chỉ trích</i></b>"}, {"question": "Which of the following best paraphrases the underlined sentence in paragraph 3?", "choices": ["The ao dai, known for its elegance and modesty, represents a blend of Vietnamese fashion that embodies cultural identity and pride.", "As a traditional dress, the ao dai reflects the combination of sophistication and simplicity in Vietnamese fashion, representing the nation&#x27;s cultural values.", "The graceful ao dai, a traditional Vietnamese attire, signifies the blend of elegance and restraint, illustrating the pride and identity of Vietnamese culture", "Known as a traditional dress, the ao dai beautifully combines elegance with symbol of Vietnam&#x27;s cultural identity and pride."], "correctIndex": 2, "explain": "<b><i> C. the graceful ao dao = a graceful traditional dress, signifies the blend of … = exemplifies the fusion of …</i></b>"}, {"question": "The word <b>their </b>in paragraph 4 refers to _______", "choices": ["Vietnamese cuisine", "Vietnamese people", "Traditional art forms", "Agricultural heritage"], "correctIndex": 1, "explain": "<b><i> B. Vietnamese people. </i></b><br><b><i>A, C, D Đều chỉ định là vật, không thể chủ động continue to honor …</i></b>"}, {"question": "Which of the following is TRUE according to the passage?", "choices": ["Vietnamese cultural identity is static and unchanging", "Modernization has completely erased Vietnamese traditions.", "Vietnamese cuisine has gained international recognition.", "Water puppetry is no longer practiced in Vietnam."], "correctIndex": 2, "explain": "<b><i> C. Vietnamese cuisine has gained international recognition. Trích từ đoạn đầu paragraph 3 “ Vietnamese cuisine is celebrated worldwide…” </i></b><br><b><i>A. Vietnamese cultural identity is static and unchanging → Trái với đoạn 4: “remains resilient while adapting to modernization”</i></b><br><b><i>B. Modernization has completely erased Vietnamese traditions. → Trái nghĩa với: “</i>the Vietnamese people continue to honor their traditions”</b><br><b><i>D. Water puppetry is no longer practiced in Vietnam. → Sai vì bài nói “continue to thrive”</i></b>"}, {"question": "In which paragraph does the writer state that Vietnamese cultural identity is influenced by both internal and external factors?", "choices": ["Paragraph 1", "Paragraph 2", "Paragraph 3", "Paragraph 4"], "correctIndex": 0, "explain": "<b><i> A. Paragraph 1 yêu cầu bài đối chiếu tương đồng với “Vietnam&#x27;s cultural identity is a fusion of indigenous traditions and external influences”</i></b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 53-60: </b>Read the passage carefully<br>Keeping up with what is happening in the world is generally seen as an essential part of being a well-informed and educated citizen. Watching, listening o or reading the news can satisfy our curiosity, make us think, help us make choices and even avoid danger. However, people are increasingly wondering if staying up to date with what is going on is good for us.<br>The frequency, speed and way we access news has completely changed over the past few decades. Whereas previously most newspapers were published daily and TV and radio news broadcasts were <b>limited</b>, now we are constantly bombarded with news from all sides, we have 24-hour news channels.<br>The content of news reports is almost always negative.<b> (I)</b> Throughout history, our survival has depended on noticing threats and avoiding danger, so the human brain is hard-wired to seek out information that is frightening or alarming.<b> (II) </b>It is about humans paying more attention to negative things because that kept us alive in the past and this is reflected in the news we consume.<b> (Ill)</b> In addition, because people now use smartphones to record events live, the news we see has beçome far more graphic and shocking. (<b>IV)</b><br>Recent studies have shown that our news habits have disadvantages for our physical and emotional health. In one survey, over 50 percent of Americans reported that the news caused them<b> </b>stress and anxiety, often causing tiredness or poor sleep. Research by schology expert Graham Davey has also proved that watching terrible or sad news on TV can worsen people&#x27;s moods and make them<b> </b>worry more about their own lives. Exposure to this ever-increasing bad news can <b>take a toll on </b>our positivity and affect our health. While it is true that staying aware and informed is not a bad thing, we<u> </u><b><u>should not forget that we have a choice, not only about how much news we consume, but equally importantly about the kind of news we want to see.</u></b>", "cauHoi": [{"question": "The word <b>limited </b>in paragraph 2 is <b>OPPOSITE </b>in meaning to", "choices": ["infinite", "restricted", "reliable", "harmonious"], "correctIndex": 0, "explain": "<b><i>→ A. infinite (adj): vĩnh cửu &gt;&lt; limited (adj): bị giới hạn</i></b><br><b><i>B. Restricted (adj or V-ed): bị giới hạn, được áp dụng trên một khu vực nào đó → Chưa phù hợp ngữ cảnh. </i></b><br><b><i>C. Reliable (adj): Đáng tin → không phù hợp nghĩa đối chiếu.</i></b><br><b><i>D. Harmonious (adj): hoà hợp → không phù hợp nghĩa đối chiếu</i></b>"}, {"question": "Where in paragraph 3 does the following sentence best fit?<br><b>“There is a concept known as &quot;negativity bias&quot;.</b>", "choices": ["I", "II", "III", "IV"], "correctIndex": 2, "explain": "<b><i>→ C. III. “a concept as negativity bias” → “paying more attention to negative things …”</i></b>"}, {"question": "Which of the following best summarizes paragraph 3?", "choices": ["The news focuses mostly on positive events, which helps people feel better.", "Humans tend to pay more attention to negative news because it has helped us survive in the past.", "News reports today are less shocking and more focused on personal stories.", "The news today is about entertaining content rather than alarming or frightening events."], "correctIndex": 1, "explain": "<b><i>→ B là phù hợp nhất. Trong đó diễn đạt đầy đủ ý từ bài, keyword mình có “attention to negative news … helped us survive in the past” = “The content of news reports … always negative” - “Throughout history, our survival has depended on noticing threats and avoiding danger”</i></b><br><b><i>A. Không phù hợp. Câu có đề cập “The news focuses mostly on positive events … helps people feel better” trái với đoạn được trích trong P3 như sau “Throughout history, our survival has depended on noticing threats and avoiding danger”. </i></b><br><b><i>C. Không phù hợp. Trong câu có “reports today are less shocking …”, trái ý với đoạn “the news we see has beçome far more graphic and shocking”. </i></b><br><b><i>D. Không phù hợp. Trong câu có “The news today is about entertaining content”, trái ý với đoạn “The content of news reports is almost always negative”</i></b>"}, {"question": "The phrase <b>take a toll on</b> in paragraph 4 could be best replaced by ______", "choices": ["pay attention to", "cause harm to", "bring benefits to", "lend support to"], "correctIndex": 1, "explain": "<b><i>→ B. cause harm to. Với từ toll (n) mang nghĩa a high degree of suffering or damage (Cambridge Dictionary). </i></b><br><b><i>A. pay attention to (Vphrase): chú ý tới → không phù hợp nghĩa đối chiếu. </i></b><br><b><i>C. bring benefits to (Vphrase): mang lợi ích đến → không phù hợp nghĩa đối chiếu. </i></b><br><b><i>D. lend support to (Vphrase): cho mượn sự hỗ trợ đến … → không phù hợp nghĩa đối chiếu.</i></b>"}, {"question": "Which of the following is NOT mentioned as one of the effects that news can have on humans according to recent studies?", "choices": ["worry", "tiredness", "sadness", "poor sleep"], "correctIndex": 2, "explain": "<b><i>→ C. sadness. Từ “recent studies” trong đoạn P4, ta có đề cập đến news cause “stress and anxiety” (dòng 2), “tiredness or poor sleep” (Dòng 3), “worry” (dòng 4). “Sadness” không được đề cập và cũng không có từ nào quy chiếu đồng nghĩa.</i></b>"}, {"question": "Which of the following is TRUE according to the passage?", "choices": ["Watching negative news regularly has no real impact on people&#x27;s mental or physical health.", "We can control both the amount and type of news we consume, which helps reduce its harmful effects.", "The news today focuses mainly on positive stories that make people feel less stressed and more relaxed.", "News consumption has decreased because many people no longer find it relevant or interesting to keep up with."], "correctIndex": 1, "explain": "<b><i>→ B là đúng. </i></b><br><b><i>A không phù hợp vì toàn bài có sự đề cập về negative news có ảnh hưởng đến sức khoẻ người xem. </i></b><br><b><i>C không phù hợp vì trong bài có đề cập tới “The content of news reports” ở đầu Paragraph 3.</i></b><br><b><i>D. không phù hợp vì bài có đề cập tới việc người ta vẫn find và pay attention to negative news. </i></b>"}, {"question": "Which of the following best paraphrases the underlined sentence in paragraph 5?", "choices": ["We should stop watching the news entirely to avoid its harmful effects.", "The news should be controlled by the government to limit negative impacts.", "It is important to be mindful of both how much and what kind of news we consume.", "It doesn&#x27;t matter what kind of news we watch as long as we stay informed."], "correctIndex": 2, "explain": "<b><i>→ C phù hợp theo các keywords để đối chiếu. “equally importantly about the kind of news we want to see” “be mindful … news we consume”</i></b><br><b><i>A, B, D đều không phù hợp về ý nghĩa truyền đạt. </i>Câu 60.</b> Which of the following best<b> </b>summarizes the passage?"}, {"question": "", "choices": ["People are generally unaffected by the news, and it has no significant impact on their emotional or physical well-being.", "Watching the news can harm our well-being, and it&#x27;s better to stop watching it altogether to protect our health.", "Negative news contributes to stress and anxiety, but the problem lies in how it&#x27;s presented, not the news itself.", "Staying informed is important, but excessive negative news can harm our health, so we must choose carefully."], "correctIndex": 3, "explain": "<b><i>→ D là phù hợp nhất. Với đại ý phù hợp với dòng gạch chân cuối đoạn 4.</i></b><br><b><i>A, B, và C có thể sử dụng phương pháp loại trừ từ bài đọc. Trong đó A có nói về “news has no significant impact …” không match với toàn bài. B lại truyền đạt việc “stop watching” nhưng đoạn gạch chân có đề cập rằng chúng ta vẫn có thể xem nhưng hãy mindful với những gì mình chọn xem. Và C lại mang hướng nói về vấn đề news truyền đạt mới tiêu cực chứ news không tiêu cực trái với bài đề cập rằng “the content of news reports is almost always negative”.</i></b>"}], "khongXaoTron": true}], "kh": [{"noiDungChung": "<b>MÔN HOÁ - Dựa vào thông tin dưới đây để trả lời các Câu từ 103 đến 105 </b><br>Độ tan trong nước của một chất là số gam chất tan có thể <b>tan trong 100 g nước</b> đề tạo thành dung dịch bão hòa. Dung dịch bão hòa là dung dịch không có khả năng hòa tan thêm chất tan. Đa số độ tan các chất rắn tăng khi nhiệt độ tăng. Khi giảm nhiệt độ, phần chất tan tách ra khỏi dung dịch gọi là hiện tượng kết tinh.<br>Để tách lấy lượng phân bón Kali người ta thường tách KCl ra khỏi quặng Sylvinite, thành phần chính của quặng là \\(NaCl.KCl\\). Vì NaCl và KCl có nhiều tính chất tương tự nhau nên người ta không dùng phương pháp hóa học để tách chúng. Thực tế người ta dựa vào độ tan khác nhau trong nước theo nhiệt độ để tách hai chất này.<br>Bảng độ tan cùa NaCl và KCl theo nhiệt độ:<br><table class=\"bang-de\"><tr><td>Nhiệt độ \\(\\left( \\ ^{\\circ}C \\right)\\)</td><td>\\[0^{\\circ}C\\]</td><td>\\[10^{\\circ}C\\]</td><td>\\[20^{\\circ}C\\]</td><td>\\[30^{\\circ}C\\]</td><td>\\[50^{\\circ}C\\]</td><td>\\[70^{\\circ}C\\]</td><td>\\[90^{\\circ}C\\]</td><td>\\[100^{\\circ}C\\]</td></tr><tr><td>Độ tan NaCl (gam)</td><td>35,6</td><td>35,7</td><td>35,8</td><td>36,7</td><td>37,5</td><td>37,5</td><td>38,5</td><td>39,1</td></tr><tr><td>Độ \\(tanKCl\\) (gam)</td><td>28,5</td><td>32,0</td><td>34,7</td><td>42,8</td><td>48,3</td><td>48,3</td><td>53,8</td><td>56,6</td></tr></table><br>Bước 1: Hòa tan một lượng quặng Sylvinite được nghiền nhỏ vào 1000 gam nước ở \\(100^{\\circ}C\\), lọc bỏ phần không tan thu được dung dịch bão hòa.<br>Bước 2: Làm lạnh dung dịch bão hòa đến \\(0^{\\circ}C\\) (lượng nước không đồi) thấy tách \\(ra_{1}\\) gam chất rắn.<br>Bước 3: Tiếp tục cho \\(m_{1}\\) gam chất rắn này vào 100 g nước ờ \\(10^{\\circ}C\\), khuấy đều thì tách ra \\(m_{2}\\) gam chất rắn không tan.<br><b>Câu 103:</b> Cho các phát biểu sau:<br>(1) Khi tăng nhiệt độ, độ tan của chất rắn luôn tăng.<br>(2) Phần chất tan bị tách ra khỏi dung dịch có thể ở dạng muối tinh thể hoặc tinh thể ngậm nước.<br>(3) Vì NaCl và KCl có tính chất hóa học giống nhau nên khó tách chúng bằng phương pháp hóa học.<br>(4) Dung dịch bão hòa là dung dịch có thể hòa tan thêm chất tan.", "cauHoi": [{"question": "Phát biểu đúng là", "choices": ["(1), (2).", "(2), (3).", "(2), (3), (4).", "(3), (4)."], "correctIndex": 1, "explain": ""}, {"question": "Hòa tan một lượng KCl 100 gam nước \\(100^{\\circ}C\\) thu được dung dịch bão hòa. Hạ nhanh nhiệt độ xuống \\(10^{\\circ}C\\), tính khối lượng KCl bị kết tinh.", "choices": ["24,3g.", "24,6g", "24,9g", "24,5g"], "correctIndex": 1, "explain": "<b>Hướng dẫn</b>: Khối lượng KCl bị kết tinh = 56,6 – 32 = 24,6 gam"}, {"question": "Giá trị của \\(m_{1}\\) và \\(m_{2}\\) trong thí nghiệm trên là", "choices": ["316 g và \\(254,9g\\).", "316 g và 249 g .", "319 g và \\(254,9g\\).", "319 g và \\(254,9g\\)."], "correctIndex": 1, "explain": "<b>Hướng dẫn</b>: Tại 100<sup>0</sup>C: trong 1000 gam H<sub>2</sub>O, độ tan của NaCl = 391 gam và KCl = 566 gam<br>Tại 0<sup>0</sup>C: trong 1000 gam H<sub>2</sub>O, độ tan của NaCl = 356 gam và KCl = 285 gam<br>\\(\\Rightarrow\\) mNaCl tách ra = 391 – 356 = 35 gam<br>\\(\\Rightarrow\\) mKCl tách ra = 566 – 285 = 281 gam<br>\\(\\Rightarrow\\) m<sub>1</sub> = 35 + 281 = 316 gam<br>Tại 10<sup>0</sup>C: trong 100 gam H<sub>2</sub>O, độ tan của NaCl = 35,7 gam và KCl = 32 gam<br>Nhận xét: vì khả năng tan của NaCl là 35,7 gam/100g H<sub>2</sub>O, nên khi mNaCl = 35 gam \\(\\Rightarrow\\) NaCl đã tan hết.<br>m<sub>2</sub> = mKCl kết tinh = 281 – 32 = 249 gam"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN LÝ - Dựa vào thông tin dưới đây để trả lời các Câu từ 106 đến 108 </b><br>Trong các hiện tượng điện từ học, khi từ thông qua một mạch dẫn kín biến thiên theo thời gian, trong mạch có thể xuất hiện một suất điện động và dòng điện tương ứng. Hiện tượng này được nghiên cứu trong cảm ứng điện từ và có liên quan đến chiều dòng điện sinh ra, được xác định theo nguyên tắc chống lại sự biến đổi đã gây ra nó.<br>Bên cạnh đó, trong một số mạch điện, khi cường độ dòng điện biến thiên, từ trường do chính dòng điện đó sinh ra cũng thay đổi và gây ra hiện tượng tự cảm. Các hiện tượng trên đều đóng vai trò quan trọng trong nhiều thiết bị kĩ thuật hiện đại.<br>Trong lĩnh vực xử lí tín hiệu âm thanh, có những thiết bị thực hiện sự <b>chuyển đổi giữa dao động cơ học và tín hiệu điện</b>. Khi sóng âm truyền đến, một bộ phận thu âm dao động theo tần số và biên độ của âm thanh. Sự dao động này làm cho từ thông qua một cuộn dây gắn với bộ phận thu âm biến thiên, từ đó xuất hiện một suất điện động trong mạch kín.<br>Xét một hệ thống thu âm cụ thể, thực nghiệm cho thấy suất điện động cảm ứng \\(E_{C}\\) thu được <b>tỉ lệ thuận với tần số f</b> và <b>biên độ dao động A</b> của bộ phận thu âm trong giới hạn khảo sát.<br>Trong đó:<br>\\(E_{C}\\): suất điện động sinh ra trong mạch<br>f: tần số âm thanh (Hz)<br>A: biên độ dao động của màng rung (mm)", "cauHoi": [{"question": "Nguyên lí hoạt động của micro loại điện động dựa vào hiện tượng", "choices": ["tự cảm.", "truyền âm thanh.", "truyền dao động.", "cảm ứng điện từ."], "correctIndex": 3, "explain": ""}, {"question": "Thiết bị nào sau đây <b>không</b> dựa trên nguyên lý cảm ứng điện từ?", "choices": ["Máy phát điện.", "Loa điện động.", "Thiết bị chống trộm RF.", "Bảng mạch điện tử."], "correctIndex": 3, "explain": ""}, {"question": "Một kỹ sư đang thử nghiệm microphone với mục tiêu thu được tín hiệu mạnh nhất khi tần số và biên độ tối ưu. Khi biên độ của màng rung đạt 2 mm và tần số là 1500 Hz , microphone tạo ra một suất điện động <img class=\"anh-de\" src=\"data/anh/l4/cb325ff40e2dbcc8.png\" alt=\"\" style=\"width:78px;height:24px;vertical-align:middle\">. Nếu tần số và biên độ tăng gấp đôi suất điện động bằng:", "choices": ["0,9 V", "1,35 V", "1,8 V", "2,25 V"], "correctIndex": 2, "explain": "<b>Lời giải chi tiết:</b><br>\\(f\\ \\)tăng 2, A tăng 2 thì E tăng 4 \\(\\Rightarrow\\) \\(E_{2} = E_{1}.4 = 1,8\\ V\\)"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SINH - Dựa vào thông tin dưới đây để trả lời các Câu từ 109 đến 111</b><br>Một thí nghiệm tìm hiểu về mức độ gần gũi trong quá trình tiến hóa của bốn loài cá bằng cách so sánh protein. Một mẫu mô cơ của mỗi loài cá được đun nóng trong dung dịch để chiết xuất protein. Các chất chiết xuất protein được phân tích bằng điện di trên cùng một bản gel agarose để tách protein theo khối lượng của chúng. Một mẫu chuẩn protein (S) chứa các protein có khối lượng đã biết trước cũng được phân tích cùng. Kết quả điện di được thể hiện trong sơ đồ, mỗi dải đại diện cho một loài được khảo sát.<br><table class=\"bang-de\"><tr><td>Khối lượng phân tử protein (S) dùng làm mẫu (kDa).</td><td>Khoảng cách di chuyển tương ứng (mm)</td><td><img class=\"anh-de\" src=\"data/anh/l4/5867d6074058bd74.png\" alt=\"\" style=\"width:279px;height:223px\"></td></tr><tr><td>16</td><td>50</td><td></td></tr><tr><td>20</td><td>38</td><td></td></tr><tr><td>26</td><td>30</td><td></td></tr><tr><td>44</td><td>24</td><td></td></tr><tr><td>66</td><td>15</td><td></td></tr><tr><td>108</td><td>10</td><td></td></tr></table>", "cauHoi": [{"question": "Kết quả trên thể hiện khoảng cách di chuyển tương ứng của các protein không phụ thuộc vào", "choices": ["nồng độ agarose trong gel.", "khối lượng protein.", "diện tích bề mặt protein.", "từng loại protein khác nhau."], "correctIndex": 0, "explain": "<b>Lời giải chi tiết:</b><br>Kết quả thu được từ bảng trên cho thấy khoảng cách di chuyển tương ứng của protein tỉ lệ nghịch với khối lượng nhưng không phụ thuộc hoàn toàn vào khối lượng, vì tỉ lệ \\(\\frac{khối\\ lượng\\ 1}{khối\\ lượng\\ 2},\\ \\frac{khoảng\\ cách\\ 2}{khoảng\\ cách\\ 1}\\) cho kết quả không giống nhau. Mặt khác, các phân tử khác nhau sẽ có kích thước khác nhau, phân tử có kích thước lớn hơn sẽ đồng thời có khối lượng và diện tích bề mặt cao hơn và lực cản lên các gel cũng sẽ lớn hơn từ đó dẫn đến sự sai khác tỉ lệ giữa khối lượng và khoảng cách. Ngoài ra, nồng độ gel agarose ở mỗi tỉ lệ sẽ cho ra một kết quả nhất định nên bảng trên không chứng minh sự phụ thuộc của khoảng cách di chuyển của các protein vào nồng độ agarose trong gel."}, {"question": "Trong các loài trên, loài nào có mối quan hệ tiến hóa xa nhất với các loài còn lại?", "choices": ["Loài 3.", "Loài 1.", "Loài 2.", "Loài 4."], "correctIndex": 0, "explain": "<b>Lời giải chi tiết:</b><br>Loài 3 chỉ trùng một dải điện di so với các loài khác nên loài ba là loài có quan hệ tiến hóa xa nhất."}, {"question": "Trong các loài trên, hai loài có mối quan hệ tiến hóa gần gũi nhất là", "choices": ["loài 2 và loài 4.", "loài 1 và loài 3.", "loài 2 và loài 3.", "loài 1 và loài 4."], "correctIndex": 0, "explain": "<b>Lời giải chi tiết:</b><br>Loài 3 chỉ trùng một dải điện di so với các loài khác nên loài ba là loài có quan hệ tiến hóa xa nhất.<br>Ngược lại loài 1, loài 2, loài 4 trùng 3 dải điện di thể hiện mối quan hệ gần gũi giữa chúng, tuy nhiên loài 1 có một dải sai khác so với 2 loài còn lại nên mối quan hệ giữa hai loài 2 và 4 được xem là gần gũi nhất."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN ĐỊA - Dựa vào thông tin dưới đây để trả lời các Câu từ 112 đến 114 </b><br>Năm 2018, hoạt động xuất nhập khẩu của Việt Nam tiếp tục đạt được những kết quả ấn tượng, đóng góp tích cực vào bức tranh tăng trưởng chung của nền kinh tế cả nước. Tổng kim ngạch xuất nhập khẩu hàng hóa của cả nước năm 2018 đạt 480,19 tỷ USD, tăng 12,2% (tương ứng tăng 52,05 tỷ USD) so với năm trước.<br>Xuất khẩu tiếp tục duy trì tốc độ tăng trưởng cao, xuất khẩu năm 2018 đạt 243,48 tỷ USD, tăng 13,2% so với năm 2017. Tính theo giá trị tuyệt đối, xuất khẩu năm 2018 tăng thêm 28,36 tỷ USD so với năm trước. Giá trị nhập khẩu đạt 236,69 tỷ USD, tăng 11,1% so với năm 2017.<br>Cơ cấu hàng hóa xuất khẩu tiếp tục cải thiện theo hướng tích cực với quy mô các mặt hàng xuất khẩu tiếp tục được mở rộng. Chiếm tỷ trọng cao nhất trong cơ cấu hàng hóa xuất khẩu vẫn là nhóm hàng công nghiệp với tỷ trọng 82,8% (tăng 1,7% so với năm 2017), tiếp đến là nhóm hàng nông sản, thủy sản chiếm<br>10,9% (giảm 1,2% so với năm 2017) và nhóm hàng nhiên liệu, khoáng sản chỉ còn chiếm 1,9% tổng kim ngạch xuất khẩu (giảm 0,3% so với năm 2017).<br>Thị trường xuất khẩu được mở rộng, hàng hóa xuất khẩu của Việt Nam đã vươn tới hầu hết các thị trường trên thế giới. Châu Á vẫn là đối tác thương mại lớn nhất của các doanh nghiệp Việt Nam (xuất khẩu chiếm 54% và nhập khẩu chiếm 80,3%); tiếp theo là châu Mỹ, châu Âu, châu Đại Dương và châu Phi.<br>Xuất nhập khẩu giữa Việt Nam và Trung Quốc lớn nhất, đạt 106,7 tỷ USD, chiếm 22,2% tổng trị giá xuất nhập khẩu của cả nước, đứng thứ hai là Hàn Quốc (13,7%), Hoa Kỳ (12,6%), Nhật Bản (7,9%).<br>(Nguồn:“Báo cáo xuất nhập khẩu Việt Nam năm 2018”, Bộ công thương)", "cauHoi": [{"question": "Chiếm tỉ trọng cao nhất trong cơ cấu hàng hóa xuất khẩu nước ta là", "choices": ["nhóm hàng nông sản, thủy sản", "nhóm hàng công nghiệp", "nhóm hàng nhiên liệu, khoáng sản", "nhóm hàng tư liệu sản xuất."], "correctIndex": 1, "explain": "<b>Lời giải chi tiết:</b><br><b>Câu 112. Chọn B</b>. Chiếm tỉ trọng cao nhất trong cơ cấu hàng hóa xuất khẩu của Việt Nam là nhóm hàng công nghiệp với tỷ trọng 82,8% (tăng 1,7% so với năm 2017)."}, {"question": "Tính cán cân xuất nhập khẩu của Việt Nam năm 2018 và cho biết nước ta xuất siêu hay nhập siêu?", "choices": ["5,69 tỷ USD, xuất siêu.", "– 6,8 tỷ USD, nhập siêu.", "6,8 tỷ USD, xuất siêu.", "7 tỷ USD, nhập siêu."], "correctIndex": 2, "explain": "<b>Lời giải chi tiết:</b><br><b>Câu 113. Chọn C</b>. Năm 2018, giá trị xuất khẩu là 243,48 tỷ USD; giá trị nhập khẩu là 236,69 tỷ USD<br>=&gt; Cán cân XNK = 243,48 – 236,69 = 6,79 tỷ USD (làm tròn bằng 6,8 tỷ USD)"}, {"question": "Nguyên nhân nào sau đây là chủ yếu thúc đẩy thị trường xuất khẩu được mở rộng, hàng hóa xuất khẩu của Việt Nam vươn tới hầu hết các thị trường trên thế giới?", "choices": ["đẩy mạnh liên kết nước ngoài, nhu cầu tiêu dùng tăng cao.", "chất lượng cuộc sống cao, kinh tế trong nước tăng trưởng nhanh.", "hội nhập quốc tế sâu rộng, sản xuất phát triển theo hướng nâng cao chất lượng, giá trị sản phẩm.", "chính sách phát triển của Nhà nước và tác động của quá trình toàn cầu hóa ."], "correctIndex": 2, "explain": "<b>Lời giải chi tiết:</b><br>Câu 114. Chọn C<br>- Nguyên nhân chủ yếu thúc đẩy thị trường xuất khẩu được mở rộng, hàng hóa xuất khẩu của Việt Nam vươn tới hầu hết các thị trường trên thế giới là kết quả của công cuộc hội nhập quốc tế sâu rộng, sản xuất phát triển theo hướng nâng cao chất lượng, giá trị sản phẩm<br>- Công cuộc hội nhập quốc tế sâu rộng giúp nước ta mở rộng thị trường buôn bán với các nước trên thrs giới, đặc biệt là từ sau khi Việt Nam gia nhập TO, và gần đây nhất là việc tham gia vào Hiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP) đã có tác động tích cực đối với mở rộng thị trường xuất khẩu.<br>- Để có thể cạnh tranh và xâm nhập sâu rộng vào thị trường của các nước trên thế giới, bản thân chúng ta cũng cần tập trung đầu tư nâng cao chất lượng và giá trị sản phẩm, đặc biệt đối với các thị trường khó tính như châu Mỹ, châu Âu."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SỬ - Dựa vào thông tin dưới đây để trả lời các Câu từ 115 đến 117</b><br>“Năm 1945, Nhà nước Việt Nam Dân chủ Cộng hoa vừa mới ra đời đã phải đối diện với rất nhiều thách thức, khó khăn. Trong bối cảnh đó, các hoạt động đối ngoại của Nhà nước Việt Nam Dân chủ Cộng hoa nhằm mục đích bảo vệ vững chắc chính quyền cách mạng, tranh thủ sự ủng hộ quốc tế và tránh đối đầu cùng một lúc với nhiều kẻ thù.<br>Chính phủ Việt Nam đã gửi thư, công hàm đề nghị Đại hội đồng Liên hợp quốc và các nước lớn công nhận Nhà nước Việt Nam Dân chủ Cộng hoà.<br>Với Pháp, Việt Nam kí Hiệp định Sơ bộ (6/3/1946) đồng ý để quân đội Pháp thay quân đội Trung Hoa Dân quốc làm nhiệm vụ giải giáp quân đội Nhật Bản ở miền Bắc. Sau đó, Chủ tịch Hồ Chí Minh tiếp tục kí với đại diện Chính phủ Pháp bản Tạm ước Việt - Pháp (14/9/1946) để kéo dài thời gian hòa bình, chuẩn bị kháng chiến.”<br>(<i>Lịch sử 12, Bộ sách Kết nối Tri thức, NXB. Giáo Dục Việt Nam, trang 77 - 78)</i>", "cauHoi": [{"question": "Ngày 14/9/1946, Nhà nước Việt Nam Dân chủ Cộng hòa đã", "choices": ["kí Hiệp định Sơ bộ với Pháp.", "kí Hiệp định Giơ-ne-vơ với Pháp.", "kí Hiệp định Pa-ri.", "kí với đại diện Chính phủ Pháp bản Tạm ước Việt - Pháp."], "correctIndex": 3, "explain": "<b>Lời giải chi tiết:</b><br><b>Câu 115:</b> <b>Chọn câu D.</b><br><b>Giải thích: </b>Hai dòng cuối của đoạn tư liệu có nêu<b> </b><i>“</i>Sau đó, Chủ tịch Hồ Chí Minh tiếp tục kí với đại diện Chính phủ Pháp bản <u>Tạm ước Việt - Pháp (14/9/1946)</u> để kéo dài thời gian hòa bình, chuẩn bị kháng chiến.”"}, {"question": "Mục đích chủ yếu của các hoạt động đối ngoại của Nhà nước Việt Nam Dân chủ Cộng hòa sau năm 1945 là", "choices": ["mở rộng quan hệ kinh tế với các nước tư bản.", "nhanh chóng thống nhất đất nước bằng biện pháp hòa bình.", "bảo vệ chính quyền cách mạng, tranh thủ sự ủng hộ quốc tế và tránh đối đầu với nhiều kẻ thù cùng lúc.", "thiết lập liên minh quân sự với các nước lớn."], "correctIndex": 2, "explain": "<b>Lời giải chi tiết:</b><br><b>Câu 116:</b> <b>Chọn câu C.</b><br><b>Giải thích: </b>Đoạn tư liệu nêu rõ:<b> </b>Năm 1945, Nhà nước Việt Nam Dân chủ Cộng hòa vừa mới ra đời, đứng trước nhiều khó khăn, thách thức. Hoạt động đối ngoại được tiến hành nhằm:<br>- Bảo vệ vững chắc chính quyền cách mạng.<br>- Tranh thủ sự ủng hộ quốc tế.<br>- Tránh đối đầu cùng một lúc với nhiều kẻ thù.<br>→ Phương án C phản ánh đầy đủ, chính xác cả ba mục tiêu.<br><b>Các phương án khác không đúng vì:</b><br><b>- A: </b>Tư liệu không đề cập trọng tâm là hợp tác kinh tế.<br>- <b>B:</b> Thống nhất đất nước không phải mục tiêu đối ngoại cấp bách năm 1945 - 1946.<br>- <b>D:</b> Việt Nam không chủ trương liên minh quân sự với các nước lớn."}, {"question": "Từ việc Chính phủ Việt Nam kí Hiệp định Sơ bộ (6/3/1946) và Tạm ước Việt - Pháp (14/9/1946), có thể rút ra nhận xét nào sau đây về đường lối đối ngoại của ta trong giai đoạn 1945 - 1946?", "choices": ["Kiên quyết dùng vũ lực để giải quyết mọi xung đột.", "Cứng rắn tuyệt đối, không nhân nhượng với kẻ thù.", "Mềm dẻo, linh hoạt, biết nhân nhượng có nguyên tắc để bảo vệ lợi ích dân tộc.", "Phụ thuộc hoàn toàn vào sự giúp đỡ của các nước lớn."], "correctIndex": 2, "explain": "<b>Lời giải chi tiết:</b><br><b>Câu 117:</b> <b>Chọn câu C.</b><br><b>Giải thích: </b>Từ các sự kiện trong tư liệu: Kí Hiệp định Sơ bộ (6/3/1946): chấp nhận cho quân Pháp ra Bắc thay quân Trung Hoa Dân quốc. Kí Tạm ước Việt - Pháp (14/9/1946): kéo dài thời gian hòa bình, chuẩn bị kháng chiến lâu dài.<br>→ Những quyết định này cho thấy:<br>- Ta không thỏa hiệp vô nguyên tắc, mà chủ động nhân nhượng có tính toán.<br>- Mục tiêu cao nhất là bảo vệ thành quả cách mạng, tránh thế bất lợi khi phải đối đầu cùng lúc với nhiều lực lượng thù địch.<br>Vì vậy, phương án C khái quát đúng bản chất đường lối đối ngoại của Việt Nam giai đoạn 1945 - 1946.<br><b>Các phương án khác không đúng vì:</b><br><b>- A: </b>Trái với thực tế vì ta chủ trương hòa hoãn, tranh thủ thời gian để chuẩn bị lực lượng cho cuộc kháng chiến lâu dài.<br><b>- B: </b>Không đúng vì ta chủ trương nhân nhượng có chiến lược với kẻ thù.<br><b>- D: </b>Ta giữ vững độc lập, tự chủ, không phụ thuộc nước lớn."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN KTPL - Dựa vào thông tin dưới đây để trả lời các Câu từ 118 đến 120 </b><br>An và Khang quyết định khởi nghiệp với ý tưởng mở một cửa hàng bánh ngọt kết hợp quán cà phê. Sau khi lên ý tưởng, họ đã thiết kế thực đơn bao gồm nhiều loại bánh ngọt và đồ uống đa dạng, với giá cả phù hợp cho nhóm khách hàng mục tiêu là giới trẻ. Trong quá trình chuẩn bị, An đảm nhận việc quảng bá và tuyển dụng nhân sự, trong khi Khang lo phần tài chính và quản lý nguồn nguyên liệu. Họ dự định sử dụng bao bì và vật dụng thân thiện với môi trường như túi giấy và ống hút tre như là một hành động bảo vệ môi trường. Với niềm tin vào ý tưởng độc đáo và lượng khách hàng tiềm năng, An và Khang tin rằng họ sẽ dễ dàng nhận được nguồn vốn vay từ ngân hàng để thực hiện hoạt động kinh doanh.", "cauHoi": [{"question": "Việc sử dụng túi giấy và ống hút tre là biểu hiện của trách nhiệm xã hội nào?", "choices": ["Trách nhiệm pháp lý.", "Trách nhiệm đạo đức.", "Trách nhiệm kinh tế.", "Trách nhiệm nhân văn."], "correctIndex": 1, "explain": "<b>Lời giải chi tiết:</b><br><b>Giải thích:</b> Việc sử dụng túi giấy, ống hút tre nhằm hạn chế rác thải, bảo vệ môi trường là hành vi tự giác vì cộng đồng, không bắt buộc bởi pháp luật → thể hiện <b>trách nhiệm đạo đức</b> của doanh nghiệp đối với xã hội."}, {"question": "Yếu tố nào quan trọng nhất để ngân hàng đồng ý cấp tín dụng cho dự án khởi nghiệp của An và Khang?", "choices": ["Ý tưởng kinh doanh độc đáo sẽ thu hút sự quan tâm của ngân hàng.", "Quy mô cửa hàng và số lượng khách tiềm năng.", "Kế hoạch kinh doanh chi tiết khả thi, đáp ứng các yêu cầu của ngân hàng.", "Quan hệ đối tác uy tín giúp tăng độ tin cậy của dự án."], "correctIndex": 2, "explain": "<b>Lời giải chi tiết:</b><br><b>Đáp án: C. Kế hoạch kinh doanh chi tiết khả thi, đáp ứng các yêu cầu của ngân hàng.</b><br><b>Giải thích:</b> Ngân hàng quan tâm nhất đến <b>tính khả thi và hiệu quả tài chính</b> của dự án (kế hoạch vốn, doanh thu, rủi ro, khả năng trả nợ…), không chỉ là ý tưởng hay hay quy mô lớn."}, {"question": "Theo tình huống trên, bước nào trong quá trình lập kế hoạch kinh doanh đã được An và Khang<br>thực hiện?", "choices": ["Xác định mục tiêu và chiến lược kinh doanh.", "Đánh giá cơ hội, rủi ro và biện pháp xử lý kinh doanh.", "Phân tích điều kiện thực hiện ý tưởng kinh doanh.", "Tóm tắt tổng kết kế hoạch kinh doanh."], "correctIndex": 2, "explain": "<b>Lời giải chi tiết:</b><br><b>Đáp án: C. Phân tích điều kiện thực hiện ý tưởng kinh doanh.</b><br><b>Giải thích:</b> An và Khang đã phân công nhân sự, chuẩn bị tài chính, nguyên liệu, quảng bá, tuyển dụng… → đây là bước <b>phân tích các điều kiện để thực hiện ý tưởng kinh doanh</b>."}], "khongXaoTron": true}]};
